<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #090b10;
      --panel: #121722;
      --panel-soft: #182030;
      --text: #f4f7fb;
      --muted: #9aa6b8;
      --danger: #ff4d6d;
      --danger-dark: #be123c;
      --line: rgba(255, 255, 255, 0.12);
      --shadow: 0 28px 80px rgba(0, 0, 0, 0.55);
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      display: grid;
      place-items: center;
      background:
        radial-gradient(circle at top left, rgba(93, 95, 239, 0.22), transparent 32rem),
        radial-gradient(circle at bottom right, rgba(255, 77, 109, 0.16), transparent 30rem),
        var(--bg);
      color: var(--text);
      padding: 2rem;
    }

    main {
      width: min(100%, 58rem);
    }

    .preview-card {
      overflow: hidden;
      border: 1px solid var(--line);
      border-radius: 1.5rem;
      background: linear-gradient(145deg, rgba(18, 23, 34, 0.96), rgba(13, 17, 25, 0.94));
      box-shadow: var(--shadow);
    }

    .image-wrap {
      position: relative;
      aspect-ratio: 16 / 10;
      background: #06080d;
    }

    .image-wrap img {
      width: 100%;
      height: 100%;
      display: block;
      object-fit: cover;
    }

    .image-wrap::after {
      content: "";
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(9, 11, 16, 0.56), transparent 45%);
      pointer-events: none;
    }

    .card-body {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1.5rem;
      padding: 1.35rem;
    }

    .eyebrow {
      margin: 0 0 0.25rem;
      color: var(--muted);
      font-size: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.1em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(1.5rem, 4vw, 2.35rem);
      line-height: 1.1;
    }

    button {
      border: 0;
      border-radius: 999px;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      transition: transform 160ms ease, background 160ms ease, border-color 160ms ease;
    }

    button:hover {
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid rgba(255, 255, 255, 0.86);
      outline-offset: 3px;
    }

    .trigger {
      flex: 0 0 auto;
      min-width: 9rem;
      padding: 0.9rem 1.25rem;
      background: linear-gradient(135deg, var(--danger), var(--danger-dark));
      color: white;
      box-shadow: 0 16px 30px rgba(190, 18, 60, 0.34);
    }

    .modal {
      position: fixed;
      inset: 0;
      display: none;
      place-items: center;
      padding: 1.5rem;
      background: rgba(3, 5, 10, 0.72);
      backdrop-filter: blur(14px);
      z-index: 10;
    }

    .modal.is-open {
      display: grid;
    }

    .dialog {
      width: min(100%, 30rem);
      border: 1px solid var(--line);
      border-radius: 1.4rem;
      background: linear-gradient(160deg, var(--panel), #0c1018);
      box-shadow: var(--shadow);
      padding: 1.5rem;
      animation: rise 180ms ease-out;
    }

    @keyframes rise {
      from {
        opacity: 0;
        transform: translateY(0.75rem) scale(0.98);
      }

      to {
        opacity: 1;
        transform: translateY(0) scale(1);
      }
    }

    .dialog-icon {
      width: 3.25rem;
      height: 3.25rem;
      display: grid;
      place-items: center;
      margin-bottom: 1rem;
      border-radius: 1rem;
      background: rgba(255, 77, 109, 0.14);
      color: #ff8fa3;
      font-size: 1.55rem;
    }

    .dialog h2 {
      margin: 0 0 0.55rem;
      font-size: 1.5rem;
    }

    .dialog p {
      margin: 0;
      color: var(--muted);
      line-height: 1.6;
    }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 0.75rem;
      margin-top: 1.5rem;
    }

    .secondary,
    .danger {
      padding: 0.8rem 1.05rem;
    }

    .secondary {
      border: 1px solid var(--line);
      background: var(--panel-soft);
      color: var(--text);
    }

    .secondary:hover {
      background: #202a3d;
    }

    .danger {
      background: var(--danger);
      color: white;
    }

    .danger:hover {
      background: #ff3158;
    }

    @media (max-width: 42rem) {
      body {
        padding: 1rem;
      }

      .card-body,
      .dialog-actions {
        align-items: stretch;
        flex-direction: column;
      }

      .trigger,
      .dialog-actions button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main>
    <section class="preview-card" aria-labelledby="image-title">
      <div class="image-wrap">
        <img
          src="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1400 875'%3E%3Cdefs%3E%3ClinearGradient id='sky' x1='0' y1='0' x2='1' y2='1'%3E%3Cstop stop-color='%2323395f'/%3E%3Cstop offset='.55' stop-color='%23734c76'/%3E%3Cstop offset='1' stop-color='%23d0785c'/%3E%3C/linearGradient%3E%3ClinearGradient id='water' x1='0' y1='0' x2='0' y2='1'%3E%3Cstop stop-color='%23142636'/%3E%3Cstop offset='1' stop-color='%23070b12'/%3E%3C/linearGradient%3E%3C/defs%3E%3Crect width='1400' height='875' fill='url(%23sky)'/%3E%3Ccircle cx='1050' cy='205' r='85' fill='%23ffd08a' opacity='.9'/%3E%3Cpath d='M0 470 220 270 360 420 545 210 760 470Z' fill='%23101824'/%3E%3Cpath d='M310 470 570 230 830 470Z' fill='%23182234'/%3E%3Cpath d='M690 470 930 280 1170 470Z' fill='%23111825'/%3E%3Crect y='470' width='1400' height='405' fill='url(%23water)'/%3E%3Cpath d='M0 640c160-50 280 48 450 0s285-54 458 0 320 42 492-7v242H0Z' fill='%23060a10' opacity='.55'/%3E%3Cpath d='M255 535h305l65 90H190Z' fill='%23253346'/%3E%3Cpath d='M240 625h385v145H240Z' fill='%23131a27'/%3E%3Cpath d='M300 625h95v145h-95zM445 625h105v75H445z' fill='%23ffd08a' opacity='.78'/%3E%3Cpath d='M160 770h520' stroke='%236c7b91' stroke-width='8' stroke-linecap='round' opacity='.45'/%3E%3C/svg%3E"
          alt="A modern cabin overlooking a calm lake at sunset"
        >
      </div>
      <div class="card-body">
        <div>
          <p class="eyebrow">Library preview</p>
          <h1 id="image-title">Lakeside Retreat</h1>
        </div>
        <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="delete-modal">
          Delete image
        </button>
      </div>
    </section>
  </main>

  <div class="modal" id="delete-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" aria-describedby="modal-description">
    <div class="dialog">
      <div class="dialog-icon" aria-hidden="true">!</div>
      <h2 id="modal-title">Delete this image?</h2>
      <p id="modal-description">
        This will remove "Lakeside Retreat" from your library. This action cannot be undone.
      </p>
      <div class="dialog-actions">
        <button class="secondary" type="button" data-close>Cancel</button>
        <button class="danger" type="button" data-confirm>Delete permanently</button>
      </div>
    </div>
  </div>

  <script>
    const modal = document.querySelector("#delete-modal");
    const trigger = document.querySelector(".trigger");
    const closeButton = document.querySelector("[data-close]");
    const confirmButton = document.querySelector("[data-confirm]");

    function openModal() {
      modal.classList.add("is-open");
      confirmButton.focus();
    }

    function closeModal() {
      modal.classList.remove("is-open");
      trigger.focus();
    }

    trigger.addEventListener("click", openModal);
    closeButton.addEventListener("click", closeModal);
    confirmButton.addEventListener("click", closeModal);

    modal.addEventListener("click", (event) => {
      if (event.target === modal) {
        closeModal();
      }
    });

    document.addEventListener("keydown", (event) => {
      if (event.key === "Escape" && modal.classList.contains("is-open")) {
        closeModal();
      }
    });
  </script>
</body>
</html>
